mapper.delete:
DELETE FROM TB_QUESTION
WHERE QUESTION_ID = #{questionId}
AND STATUS = 'OPEN'

mapper.update:
UPDATE TB_QUESTION SET STATUS = #{status},
ASSIGNED_LAWYER = #{lawyerId},
UPDATED_AT = SYSDATE WHERE QUESTION_ID = #{questionId}

mapper.select:
SELECT COUNT(*) FROM TB_QUESTION


		AND CASE_TYPE = #{caseType}


		AND TITLE LIKE '%' || #{title} || '%'
